def transfer(db,src,dst,amount):
 if type(amount)is not int or amount<=0 or src==dst:raise ValueError()
 db.execute('BEGIN')
 try:
  source=db.execute('SELECT balance FROM accounts WHERE name=?',(src,)).fetchone()
  destination=db.execute('SELECT balance FROM accounts WHERE name=?',(dst,)).fetchone()
  if source is None or destination is None or source[0]<amount:raise ValueError()
  db.execute('UPDATE accounts SET balance=? WHERE name=?',(source[0]-amount,src))
  db.execute('UPDATE accounts SET balance=? WHERE name=?',(destination[0]+amount,dst))
 except BaseException:db.rollback();raise
 else:db.commit()

