import re
def pointer(document,path):
 if path=='':return document
 if not path.startswith('/'):raise ValueError()
 value=document
 for raw in path[1:].split('/'):
  if re.search(r'~(?![01])',raw):raise ValueError()
  key=raw.replace('~1','/').replace('~0','~')
  if isinstance(value,list):
   if not re.fullmatch(r'0|[1-9][0-9]*',key):raise ValueError()
   index=0
   for digit in key:
    index=index*10+ord(digit)-48
    if index>=len(value):raise IndexError()
   value=value[index]
  elif isinstance(value,dict):value=value[key]
  else:raise ValueError()
 return value

