import sqlite3
class Queue:
 def __init__(self,path):
  self.db=sqlite3.connect(path)
  self.db.execute('CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,payload TEXT,state TEXT,until REAL,token INT)')
  self.db.commit()
 def add(self,key,payload):
  with self.db:self.db.execute("INSERT OR IGNORE INTO jobs VALUES (?,?,'ready',0,0)",(key,payload))
 def claim(self,now,lease):
  if not (0<lease):raise ValueError()
  with self.db:
   cursor=self.db.execute("UPDATE jobs SET state='leased',until=?,token=token+1 WHERE id=(SELECT id FROM jobs WHERE state='ready' OR (state='leased' AND until<=?) ORDER BY id LIMIT 1) RETURNING id,payload,token",(now+lease,now))
   try:return cursor.fetchone()
   finally:cursor.close()
 def ack(self,key,token,now):
  with self.db:
   cur=self.db.execute("UPDATE jobs SET state='done' WHERE id=? AND state='leased' AND token=? AND until>?",(key,token,now))
   return cur.rowcount==1
 def close(self):self.db.close()

